local np=require('luaray_core')
local function eq(a,b)
 if type(a)=='table' then
   if type(b)~='table' or #a~=#b then return false end
   for i=1,#a do if not eq(a[i],b[i]) then return false end end
   return true
 end
 if type(a)=='number' and type(b)=='number' then
   if a~=a and b~=b then return true end
   return a==b
 end
 if type(a)=='userdata' and type(b)=='userdata' then
   return eq(a.real,b.real) and eq(a.imag,b.imag)
 end
 return a==b
end
do -- 0 max int64 ()
 local a=np.reshape(np.array({5},np.int64),{})
 local mask=np.reshape(np.array({true},np.bool),{})
 assert(not pcall(function() np.max(a,{where=mask}) end),"extrema reject 0")
end
